package com.hoteluq.service;
import com.hoteluq.model.Reservation;import java.nio.file.*;import java.time.*;import java.util.*;
public class ReportService {public String summary(List<Reservation> data,LocalDate from,LocalDate to){var selected=data.stream().filter(r->!r.getCheckIn().isBefore(from)&&!r.getCheckIn().isAfter(to)).toList();double income=selected.stream().filter(r->r.getStatus()!=com.hoteluq.model.enums.ReservationStatus.CANCELLED).mapToDouble(Reservation::getTotal).sum();return "HOTELUQ - REPORTE DE RESERVAS\nGenerado: "+LocalDateTime.now()+"\nPeriodo: "+from+" a "+to+"\nRegistros: "+selected.size()+"\nIngresos de reservas no canceladas: $"+income+" COP\n"+selected.stream().map(r->r.getId()+" | "+r.getCustomer().getName()+" | Hab. "+r.getRoom().getNumber()+" | "+r.getCheckIn()+" | "+r.getStatus()).reduce("",(a,b)->a+b+"\n");}public Path exportTxt(String content,Path path)throws java.io.IOException{Files.writeString(path,content);return path;}}
